import{c as s,Q as t,j as n,m as e}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"一文掌握 Claude Fable 5 实战：Prompt · 上下文管理 · Loop","description":"","frontmatter":{"url":"https://x.com/wquguru/status/2072665421099253843","title":"一文掌握 Claude Fable 5 实战：Prompt · 上下文管理 · Loop","author":"wquguru","archived":"2026-07-03T00:00:00.000Z","handle":"@wquguru","published":"2026-07-02T00:00:00.000Z","stats":"66 likes · 13 retweets · 149 bookmarks · 41162 views","tags":["fable5","prompt-engineering","loop","context-management","zh-cn","reasoning-extraction"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-02-@wquguru-253843.md","filePath":"research/tweets/2026-07-02-@wquguru-253843.md","lastUpdated":1785909234000}'),l={name:"research/tweets/2026-07-02-@wquguru-253843.md"};function o(p,a,i,r,d,c){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="一文掌握-claude-fable-5-实战-prompt-·-上下文管理-·-loop-—-wquguru" tabindex="-1">一文掌握 Claude Fable 5 实战：Prompt · 上下文管理 · Loop — @wquguru <a class="header-anchor" href="#一文掌握-claude-fable-5-实战-prompt-·-上下文管理-·-loop-—-wquguru" aria-label="Permalink to &quot;一文掌握 Claude Fable 5 实战：Prompt · 上下文管理 · Loop — @wquguru&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/wquguru/status/2072665421099253843" target="_blank" rel="noreferrer">https://x.com/wquguru/status/2072665421099253843</a><strong>作者</strong>：wquguru（@wquguru） <strong>發布日期</strong>：2026-07-02 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article（簡體中文） <strong>統計</strong>：66 likes · 13 retweets · 149 bookmarks · 41162 views</p><hr><h2 id="全文摘要-原文-8-357-字-節錄核心技術段落" tabindex="-1">全文摘要（原文 8,357 字，節錄核心技術段落） <a class="header-anchor" href="#全文摘要-原文-8-357-字-節錄核心技術段落" aria-label="Permalink to &quot;全文摘要（原文 8,357 字，節錄核心技術段落）&quot;">​</a></h2><p>用好 Fable 5，離不開三塊：提示詞工程（邊界設計）、長時間運行上下文管理（檢查點/記憶/進度驗證）、Loop（/goal + /loop + 並行子代理）。</p><h3 id="第一部分-理解-fable-5-能力跃迁" tabindex="-1">第一部分：理解 Fable 5 能力跃迁 <a class="header-anchor" href="#第一部分-理解-fable-5-能力跃迁" aria-label="Permalink to &quot;第一部分：理解 Fable 5 能力跃迁&quot;">​</a></h3><p>六項能力跃迁（vs Opus 4.8）：</p><ol><li><strong>長時間自主運行</strong>：設計目標為「跨越多天的目標導向任務」</li><li><strong>首次正確率</strong>：複雜但定義清晰的問題一稿就對</li><li><strong>視覺理解</strong>：密集技術圖像/網頁截圖解讀大幅提升，使用更少 output token</li><li><strong>企業工作流</strong>：財報/表格/文檔，更守指令、不越界</li><li><strong>代碼審查</strong>：跨 codebase bug 召回率更高（注意：進攻性網安被安全分類器規避）</li><li><strong>委派與協作</strong>：可穩定管理 50+ 並行子代理，支持異步通信</li></ol><p><strong>舊 Prompt 失效原因</strong>：Opus 4.8 時代的逐條限制對 Fable 5 是天花板。原則：<strong>少寫指令，多給意圖</strong>。</p><h3 id="第二部分-寫好-fable-5-prompt" tabindex="-1">第二部分：寫好 Fable 5 Prompt <a class="header-anchor" href="#第二部分-寫好-fable-5-prompt" aria-label="Permalink to &quot;第二部分：寫好 Fable 5 Prompt&quot;">​</a></h3><p><strong>四要素結構（最小可行框架）</strong>：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我正在為[服務對象]做[更大的任務]。</span></span>
<span class="line"><span>他們需要[這份輸出用來支撐什麼]。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>請求：[一句話說清你具體要什麼]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>輸出格式：[結果如何組織和交付——篇幅、結構、風格]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>約束：[過程中絕不允許發生的事——不做什麼、不假定什麼]</span></span></code></pre></div><p><strong>Effort 選擇法則</strong>：先按默認 high 跑；超時或「順手優化」太多降到 medium；質量要求極高上 xhigh；<strong>不要在簡單任務上用高 effort</strong>（Fable 會收集不需要的上下文並反覆推敲）。</p><h3 id="第三部分-管好長時間自主運行上下文" tabindex="-1">第三部分：管好長時間自主運行上下文 <a class="header-anchor" href="#第三部分-管好長時間自主運行上下文" aria-label="Permalink to &quot;第三部分：管好長時間自主運行上下文&quot;">​</a></h3><p><strong>檢查點</strong>（官方推薦最簡寫法）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在你繼續之前先暫停。列出你計劃採取的行動，</span></span>
<span class="line"><span>讓我確認後再繼續</span></span></code></pre></div><p><strong>進度驗證</strong>（防虛報進度）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>沒有對應工具結果支撐的事項，標注為&quot;未驗證&quot;，不要報告為&quot;已完成&quot;。</span></span></code></pre></div><p>→ 核心原理：把聲明和證據綁定，模型不能只說「測試通過了」，必須確認真的運行了測試。</p><p><strong>記憶系統</strong>（最高回報的基礎設施，一個 Markdown 文件夾即可）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把本次工作中學到的經驗寫入 notes/ 目錄：</span></span>
<span class="line"><span>每條經驗一個文件，頂部一行摘要。</span></span>
<span class="line"><span>被糾正的錯誤和驗證過的有效方法都要記錄，並寫明為什麼重要。</span></span>
<span class="line"><span>倉庫或聊天記錄裡已有的信息不要重複。</span></span>
<span class="line"><span>優先更新已有筆記，而不是新建重複條目。</span></span>
<span class="line"><span>被證明是錯的筆記要刪除。</span></span></code></pre></div><p><strong>Overnight 總結風格</strong>（長時間無人在場後的輸出格式）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果你已經長時間在用戶不在場的情況下工作</span></span>
<span class="line"><span>（跨夜、跨大量工具調用、自他們上次發言以來），</span></span>
<span class="line"><span>你的最終消息是他們對這一切的第一眼。</span></span>
<span class="line"><span>把它寫成重新鋪墊，而不是工作線程的延續：</span></span>
<span class="line"><span>先說結果，再說需要他們做的一兩件事，每件都當作新信息來解釋。</span></span>
<span class="line"><span>寫完整句子。拼出術語全稱。不要用箭頭鏈、連字符堆疊的複合詞。</span></span></code></pre></div><h3 id="第四部分-設計-loop" tabindex="-1">第四部分：設計 Loop <a class="header-anchor" href="#第四部分-設計-loop" aria-label="Permalink to &quot;第四部分：設計 Loop&quot;">​</a></h3><p><strong>Claude Code 四種循環</strong>：</p><ol><li>回合制（手動檢查 → 下一輪指令）</li><li>目標制 <code>/goal</code>：一直迭代到條件達標</li><li>定時制 <code>/loop</code>（本地）/ <code>/schedule</code>（雲端）</li><li>主動式：schedule + goal + Dynamic Workflows + Auto mode 組合</li></ol><p><strong><code>/goal</code> 最佳實踐</strong>（確定性標準最有效）：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/goal 把首頁 Lighthouse 性能分數提到 90 以上，最多嘗試 5 次</span></span>
<span class="line"><span>/goal 修復所有失敗的集成測試，最多迭代 8 輪。每輪結束後列出剩餘失敗的測試數量和失敗原因。</span></span></code></pre></div><p><strong>四件套示例</strong>（處理用戶反饋流）：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/schedule 每小時執行一次：</span></span>
<span class="line"><span>檢查 #project-feedback 頻道的新 bug 報告。</span></span>
<span class="line"><span>/goal 本輪發現的所有報告都完成分類、處理和回復才算完成。</span></span>
<span class="line"><span>修復 bug 時，用 Dynamic Workflow 並行在三個獨立工作樹中探索方案，</span></span>
<span class="line"><span>由一個裁判代理做對抗性審查，選擇最優方案。</span></span>
<span class="line"><span>用 auto mode 運行，全程不請求人工確認。</span></span></code></pre></div><p><strong>並行子代理三原則</strong>：</p><ol><li>能拆成並行任務的就拆</li><li>異步通信優先（不阻塞等待子代理返回）</li><li><strong>用獨立驗證替代自我批評</strong>（全新 context 的驗證子代理 &gt; 主代理自我審查）</li></ol><h3 id="第五部分-避坑" tabindex="-1">第五部分：避坑 <a class="header-anchor" href="#第五部分-避坑" aria-label="Permalink to &quot;第五部分：避坑&quot;">​</a></h3><p><strong>⚠️ 重要：復述推理會觸發 Fallback 到 Opus 4.8</strong> 任何 prompt/skill/系統提示裡含「展示你的思考過程」「解釋你的推理」類指令，可能觸發 <code>reasoning_extraction</code> 拒絕類別，導致請求 fallback 到 Opus 4.8。<strong>遷移到 Fable 5 時必須審計所有舊 skill 和系統提示</strong>，移除這類指令。</p><p><strong>偶發的提前停止</strong>：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果你陳述了下一步意圖，必須立即執行對應的工具調用，</span></span>
<span class="line"><span>不要以純文字意圖結束回合。</span></span>
<span class="line"><span>已有足夠信息時不要請求許可，直接推進。</span></span></code></pre></div><p><strong>上下文預算焦慮</strong>：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不必為上下文預算擔心。按當前任務的完整需求工作，</span></span>
<span class="line"><span>不要因為節省上下文而壓縮、總結或提前移交你的工作。</span></span></code></pre></div><p><strong>安全分類器三組</strong>：進攻性網絡安全、生物/生命科學、思考內容提取 → 建議 production 回退到 Opus 4.8。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Fable 5 實戰完整指南（中文）：四要素 prompt 框架、notes/ 記憶系統、overnight 總結風格、/goal /loop /schedule 組合、並行子代理三原則；最重要的避坑是 reasoning_extraction 指令會觸發 Fable→Opus 4.8 fallback。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>Fable 5 舊 prompt 失效原因：逐條限制是天花板，改為「多給意圖少寫指令」</li><li>進度驗證：聲明與工具結果綁定，防虛報（「未驗證」標注機制）</li><li>notes/ 記憶系統是 Fable 5 上回報率最高的基礎設施</li><li>reasoning_extraction 是 Fable→Opus fallback 的隱藏觸發條件（遷移必審舊 skill）</li><li>驗證子代理必須用全新 context（驗證者不能是執行者）</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li><code>/goal 把首頁 Lighthouse 分數提到 90，最多嘗試 5 次</code></li><li><code>/schedule 每小時 + /goal + Dynamic Workflows + auto mode</code> 四件套</li><li>成本控制六策略：按任務選模型、明確停止條件、小批量試點、確定性工作交腳本、輪詢間隔≥變化頻率、定期 /usage 復盤</li><li>作者提供 Skill：<code>npx skills add https://github.com/wquguru/skills --skill fable5-best-practice</code></li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>reasoning_extraction 避坑與本 workspace core.md 的「禁止要求展示推理」規則高度對齊，值得直接補進規則</li><li>notes/ 記憶系統與 MEMORY.md/LESSONS.md 雙軌機制有重疊，需釐清分工</li><li>overnight 總結風格 prompt 是少見的「多 agent 長時間任務後的輸出規範」，可封裝為 subagent-strategy.md 規則</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>四要素結構/記憶系統/overnight 風格/避坑全可直接套用</td></tr><tr><td>B. 創新性 (20%)</td><td>8.5/10</td><td>reasoning_extraction fallback 發現、overnight 風格 prompt 是新穎洞察</td></tr><tr><td>C. 證據品質 (20%)</td><td>8/10</td><td>引用 Anthropic 官方文檔，多個代碼示例，第一手廣泛測試</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>覆蓋 edge cases（上下文預算焦慮/安全分類器）極深</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>Fable 5 特定，但四要素結構/並行驗證原則跨模型通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.6/10</strong></td><td>9×0.3+8.5×0.2+8×0.2+9×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：reasoning_extraction 避坑需補進 core.md 或 subagent-strategy.md；notes/ 記憶系統補充 MEMORY.md；overnight 輸出風格 prompt 補充 subagent-strategy.md；四要素結構可加入 delegation-protocol.md task-templates。</p>`,52)])])}const h=s(l,[["render",o]]);export{u as __pageData,h as default};
